param([int]$HttpPort = 8765,[switch]$NoBrowser)
$ErrorActionPreference = 'Stop'
$script:st = [ordered]@{status='getrennt';error='';config=$null;events=(New-Object System.Collections.ArrayList);queue=(New-Object System.Collections.Queue);next_id=0;phase='idle';last_poll='';last_action=[DateTime]::UtcNow;buffer=(New-Object System.Collections.Generic.List[byte]);traffic=@{poll=@{rx=0;tx=0};ack=@{rx=0;tx=0};eot=@{rx=0;tx=0};block=@{rx=0;tx=0};error=@{rx=0;tx=0}}}
$script:serial=$null;$script:client=$null;$script:tcpServer=$null;$script:tcpPeer=$null
$script:recordNames=@{'1'='Rufadresse';'2'='Anzeigetext';'3'='Signalton';'4'='Rufart';'5'='Wiederholungen';'6'='Priorität';'7'='Rufstatus';'8'='Systemstatus'}
function Add-Event([string]$direction,[string]$kind,[byte[]]$raw,$extra=$null){$script:st.next_id++;$category=if($kind -in @('poll','select')){'poll'}elseif($kind -in @('ack','block_reply','select_ack')){'ack'}elseif($kind -in @('eot','empty_poll','complete','rejected')){'eot'}elseif($kind -eq 'block'){'block'}else{'error'};if($direction -in @('rx','tx')){$script:st.traffic[$category][$direction]++};if($kind -in @('poll','select')){$script:st.last_poll_at=[DateTime]::UtcNow};$hex=(($raw|ForEach-Object{$_.ToString('X2')}) -join ' ');$keep=$kind -in @('poll','select','empty_poll','ack','select_ack','eot','complete');$e=[ordered]@{id=$script:st.next_id;time=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffK');direction=$direction;kind=$kind;category=$category;keepalive=$keep;hex=$hex};if($extra){foreach($k in $extra.Keys){$e[$k]=$extra[$k]}};[void]$script:st.events.Add($e);while($script:st.events.Count -gt 500){$script:st.events.RemoveAt(0)}}
function Bcc([byte[]]$bytes,[bool]$seven){$v=0;foreach($b in $bytes){$v=$v -bxor [int]$b};if($seven){return ($v -band 127)}return ($v -band 255)}
function Decode-Block([byte[]]$raw){if($raw.Length -lt 5 -or $raw[0] -ne 1 -or $raw[2] -ne 2 -or $raw[$raw.Length-2] -ne 3){throw 'Ungültiger ESPA-Block'};$cfg=$script:st.config;$expected=Bcc $raw[1..($raw.Length-2)] $cfg.seven_bit_bcc;$records=New-Object System.Collections.ArrayList;$start=3;$limit=$raw.Length-2;for($i=3;$i -le $limit;$i++){if($i -eq $limit -or $raw[$i] -eq 30){if($i -gt $start){$sep=[Array]::IndexOf($raw,[byte]31,$start,$i-$start);if($sep -lt 0){throw 'US im Datensatz fehlt'};$id=[Text.Encoding]::ASCII.GetString($raw,$start,$sep-$start);$val=[Text.Encoding]::ASCII.GetString($raw,$sep+1,$i-$sep-1);$name=if($script:recordNames.ContainsKey($id)){$script:recordNames[$id]}else{'Unbekannt'};[void]$records.Add(@{id=$id;name=$name;value=$val})};$start=$i+1}};return @{header=[char]$raw[1];records=@($records.ToArray());bcc_ok=($raw[$raw.Length-1] -eq $expected);bcc_received=$raw[$raw.Length-1].ToString('X2');bcc_expected=$expected.ToString('X2')}}
function Handle-Bytes([byte[]]$bytes){foreach($b in $bytes){$script:st.buffer.Add($b)};while($script:st.buffer.Count){$n=$script:st.buffer.Count;if($script:st.buffer[0] -eq 1){$end=-1;for($i=1;$i -lt $n;$i++){if($script:st.buffer[$i] -eq 3){$end=$i;break}};if($end -lt 0){if($n -gt 2048){$script:st.buffer.RemoveAt(0);Add-Event rx error ([byte[]]@(1)) @{error='Block länger als 2048 Byte'}};break};if($n -lt $end+2){break};$raw=$script:st.buffer.GetRange(0,$end+2).ToArray();$script:st.buffer.RemoveRange(0,$end+2);try{$block=Decode-Block $raw;Add-Event rx block $raw @{block=$block;summary=(($block.records|ForEach-Object{"$($_.name): $($_.value)"}) -join ' · ')};if($script:st.config.mode -eq 'emulator'){Send-Control $(if($block.bcc_ok){6}else{21}) 'block_reply'}}catch{Add-Event rx error $raw @{error=$_.Exception.Message}};continue};if($n -ge 2 -and $script:st.buffer[0] -ge 48 -and $script:st.buffer[0] -le 57 -and $script:st.buffer[1] -eq 5){$r=$script:st.buffer.GetRange(0,2).ToArray();$script:st.buffer.RemoveRange(0,2);$address=[char]$r[0];Add-Event rx poll $r @{address="$address";summary="Adresse $address · ENQ"};Handle-Poll "$address";continue};$b=$script:st.buffer[0];if($b -in @(4,6,21)){$script:st.buffer.RemoveAt(0);$kind=@{4='eot';6='ack';21='nak'}[[int]$b];Add-Event rx $kind ([byte[]]@($b)) @{summary=$kind.ToUpper()};Handle-Control $kind;continue};if($n -eq 1 -and $b -ge 48 -and $b -le 57){break};$script:st.buffer.RemoveAt(0);Add-Event rx unknown ([byte[]]@($b)) @{summary='Unbekanntes Byte'}}}
function Write-Link([byte[]]$raw,[string]$kind){if($script:serial -and $script:serial.IsOpen){$script:serial.Write($raw,0,$raw.Length)}elseif($script:client -and $script:client.Connected){$script:client.GetStream().Write($raw,0,$raw.Length)}elseif($script:tcpPeer -and $script:tcpPeer.Connected){$script:tcpPeer.GetStream().Write($raw,0,$raw.Length)}else{throw 'Keine Gegenstelle verbunden'};$extra=@{summary=$kind};if($kind -eq 'block'){$block=Decode-Block $raw;$extra.block=$block;$extra.summary='Block '+$block.header+' · '+(($block.records|ForEach-Object{"$($_.name): $($_.value)"}) -join ' · ')+' · BCC '+$(if($block.bcc_ok){'OK'}else{'FEHLER'})}elseif($kind -eq 'poll' -and $raw.Length -ge 2){$extra.address=[string][char]$raw[$raw.Length-2];$extra.summary='Adresse '+$extra.address+' · ENQ'}elseif($kind -eq 'select'){$extra.summary='Auswahl / ENQ · '+(($raw|ForEach-Object{if($_ -ge 48 -and $_ -le 57){[char]$_}elseif($_ -eq 5){'ENQ'}elseif($_ -eq 4){'EOT'}else{'0x'+$_.ToString('X2')}}) -join ' ')};Add-Event tx $kind $raw $extra}
function Send-Control([int]$b,[string]$kind){Write-Link ([byte[]]@($b)) $kind}
function Handle-Poll([string]$address){$c=$script:st.config;if(-not $c -or $c.mode -ne 'emulator'){return};if($c.role -eq 'device'){if($address -eq $c.peer_address){$script:st.last_poll=$address;$script:st.last_action=[DateTime]::UtcNow;return};if($address -eq $c.local_address){if($script:st.last_poll -eq $c.peer_address){Send-Control 6 'select_ack';$script:st.phase='receiving';$script:st.last_action=[DateTime]::UtcNow}elseif($script:st.queue.Count -gt 0 -and $script:st.phase -eq 'idle'){$raw=[Text.Encoding]::ASCII.GetBytes($c.peer_address);$raw+= [byte[]]@(5);Write-Link $raw 'select';$script:st.phase='select_ack';$script:st.last_action=[DateTime]::UtcNow}else{Send-Control 4 'empty_poll'};$script:st.last_poll=''}}}
function Handle-Control([string]$kind){$c=$script:st.config;if(-not $c -or $c.mode -ne 'emulator'){return};if($kind -eq 'ack' -and $script:st.phase -eq 'select_ack' -and $script:st.queue.Count -gt 0){$m=$script:st.queue.Peek();Write-Link $m 'block';$script:st.phase='block_ack';$script:st.last_action=[DateTime]::UtcNow}elseif($kind -eq 'ack' -and $script:st.phase -eq 'block_ack'){$null=$script:st.queue.Dequeue();Send-Control 4 'complete';$script:st.phase='idle';$script:st.last_action=[DateTime]::UtcNow}elseif($kind -eq 'nak' -and $script:st.phase -in @('select_ack','block_ack')){Send-Control 4 'rejected';$script:st.phase='idle';$script:st.last_action=[DateTime]::UtcNow}elseif($kind -eq 'ack' -and $script:st.phase -eq 'polling'){$script:st.phase='idle';$script:st.last_action=[DateTime]::UtcNow}elseif($kind -eq 'eot'){$script:st.phase='idle';$script:st.last_poll='';$script:st.last_action=[DateTime]::UtcNow}}
function Tick-Controller{ $c=$script:st.config;if(-not $c -or $c.mode -ne 'emulator'){return};$connected=($script:serial -and $script:serial.IsOpen) -or ($script:client -and $script:client.Connected) -or ($script:tcpPeer -and $script:tcpPeer.Connected);if(-not $connected){return};$elapsed=([DateTime]::UtcNow-$script:st.last_action).TotalSeconds;if($script:st.phase -ne 'idle'){if($elapsed -gt 10){Send-Control 4 'timeout';$script:st.phase='idle';$script:st.last_poll='';$script:st.last_action=[DateTime]::UtcNow};return};if($c.role -ne 'controller' -or $elapsed -lt $c.poll_interval){return};if($script:st.queue.Count -gt 0){$raw=[byte[]]@(4,[byte][char]$c.local_address,5,[byte][char]$c.peer_address,5);Write-Link $raw 'select';$script:st.phase='select_ack'}else{$raw=[byte[]]@(4,[byte][char]$c.peer_address,5);Write-Link $raw 'poll';$script:st.phase='polling'};$script:st.last_action=[DateTime]::UtcNow}
function Ascii-Field([string]$s,[int]$max){$s=$s.Replace('Ä','AE').Replace('Ö','OE').Replace('Ü','UE').Replace('ä','ae').Replace('ö','oe').Replace('ü','ue').Replace('ß','ss');if(-not $s -or $s.Length -gt $max -or $s -match '[^\x20-\x7E]'){throw "Feld muss 1 bis $max druckbare ASCII-Zeichen enthalten"};return [Text.Encoding]::ASCII.GetBytes($s)}
function Make-Block($d){$c=$script:st.config;$fields=@([pscustomobject]@{id='1';value=[byte[]](Ascii-Field "$($d.address)" 16)},[pscustomobject]@{id='2';value=[byte[]](Ascii-Field "$($d.message)" 128)},[pscustomobject]@{id='3';value=[byte[]](Ascii-Field "$($d.beep)" 8)},[pscustomobject]@{id='4';value=[byte[]](Ascii-Field "$($d.call_type)" 8)},[pscustomobject]@{id='6';value=[byte[]](Ascii-Field "$($d.priority)" 8)});$list=New-Object System.Collections.Generic.List[byte];$list.AddRange([byte[]]@(1,49,2));for($j=0;$j -lt $fields.Count;$j++){if($j -gt 0){$list.Add(30)};$list.Add([byte][char]$fields[$j].id);$list.Add(31);$list.AddRange([byte[]]$fields[$j].value)};if($c.trailing_rs){$list.Add(30)};$list.Add(3);$raw=$list.ToArray();$x=Bcc $raw[1..($raw.Length-1)] $c.seven_bit_bcc;$list.Add([byte]$x);return ,$list.ToArray()}
function Start-Link($c){Stop-Link;$local="$($c.local_address)";$peer="$($c.peer_address)";if($local -notmatch '^\d$' -or $peer -notmatch '^\d$' -or $local -eq $peer){throw 'ESPA-Adressen müssen verschiedene Ziffern sein'};if($c.transport -notin @('serial','tcp_client','tcp_listen') -or $c.mode -notin @('monitor','emulator') -or $c.role -notin @('device','controller')){throw 'Betriebsart ungültig'};$c.local_address=$local;$c.peer_address=$peer;$c.poll_interval=[Math]::Max(1,[Math]::Min(60,[double]$c.poll_interval));$script:st.config=$c;$script:st.error='';$script:st.buffer.Clear();$script:st.phase='idle';$script:st.last_action=[DateTime]::UtcNow;$script:st.last_poll_at=$null;if($c.transport -eq 'serial'){$parity=switch($c.parity){'E'{[IO.Ports.Parity]::Even}'O'{[IO.Ports.Parity]::Odd}default{[IO.Ports.Parity]::None}};$stop=if([int]$c.stops -eq 2){[IO.Ports.StopBits]::Two}else{[IO.Ports.StopBits]::One};$script:serial=[IO.Ports.SerialPort]::new($c.serial_port,[int]$c.baud,$parity,[int]$c.bits,$stop);$script:serial.ReadTimeout=1;$script:serial.Open();$script:st.status='verbunden';$script:st.last_poll_at=[DateTime]::UtcNow}elseif($c.transport -eq 'tcp_client'){$script:client=[Net.Sockets.TcpClient]::new();$script:client.Connect($c.host,[int]$c.port);$script:st.status='verbunden';$script:st.last_poll_at=[DateTime]::UtcNow}else{$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Parse($c.host),[int]$c.port);$listener.Start();$script:tcpServer=$listener;$script:st.status='wartet auf TCP-Verbindung'};Add-Event system start ([byte[]]@()) @{info='Verbindung gestartet'}}
function Stop-Link{try{if($script:serial){$script:serial.Close();$script:serial.Dispose()};if($script:client){$script:client.Close()};if($script:tcpPeer){$script:tcpPeer.Close()};if($script:tcpServer){$script:tcpServer.Stop()}}catch{};$script:serial=$null;$script:client=$null;$script:tcpPeer=$null;$script:tcpServer=$null;$script:st.status='getrennt'}
function Read-Link{try{if($script:serial -and $script:serial.IsOpen -and $script:serial.BytesToRead -gt 0){$b=New-Object byte[] ([Math]::Min(4096,$script:serial.BytesToRead));$n=$script:serial.Read($b,0,$b.Length);if($n){Handle-Bytes $b[0..($n-1)]}};$conn=$script:client;if(-not $conn){$conn=$script:tcpPeer};if($conn -and $conn.Connected -and $conn.GetStream().DataAvailable){$b=New-Object byte[] 4096;$n=$conn.GetStream().Read($b,0,$b.Length);if($n -gt 0){Handle-Bytes $b[0..($n-1)]}};if($script:tcpServer -and -not $script:tcpPeer -and $script:tcpServer.Pending()){$script:tcpPeer=$script:tcpServer.AcceptTcpClient();$script:st.status='verbunden';$script:st.error='';$script:st.last_poll_at=[DateTime]::UtcNow;$script:tcpPeer.ReceiveTimeout=1};Tick-Controller}catch{$script:st.error=$_.Exception.Message;$script:st.status='Fehler'}}
function Read-HttpLine($stream){$bytes=New-Object System.Collections.Generic.List[byte];while($true){$b=$stream.ReadByte();if($b -lt 0){break};if($b -eq 10){break};if($b -ne 13){$bytes.Add([byte]$b)}};return [Text.Encoding]::ASCII.GetString($bytes.ToArray())}
function Reply($stream,[string]$status,[string]$content,[string]$type='application/json; charset=utf-8'){$bytes=[Text.Encoding]::UTF8.GetBytes($content);$head=[Text.Encoding]::ASCII.GetBytes("HTTP/1.1 $status`r`nContent-Type: $type`r`nContent-Length: $($bytes.Length)`r`nConnection: close`r`nCache-Control: no-store`r`n`r`n");$stream.Write($head,0,$head.Length);$stream.Write($bytes,0,$bytes.Length)}
function Reply-Binary($stream,[string]$status,[byte[]]$bytes,[string]$type){$crlf=[string]([char]13)+[char]10;$head=[Text.Encoding]::ASCII.GetBytes('HTTP/1.1 '+$status+$crlf+'Content-Type: '+$type+$crlf+'Content-Length: '+$bytes.Length+$crlf+'Connection: close'+$crlf+'Cache-Control: public, max-age=86400'+$crlf+$crlf);$stream.Write($head,0,$head.Length);$stream.Write($bytes,0,$bytes.Length)}
$http=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,$HttpPort);$http.Start();$url="http://127.0.0.1:$HttpPort/";Write-Host "FreeESPA läuft lokal: $url" -ForegroundColor Cyan;if(-not $NoBrowser){Start-Job {Start-Sleep -Milliseconds 600;Start-Process $using:url}|Out-Null}
try{while($true){Read-Link;if(-not $http.Pending()){Start-Sleep -Milliseconds 15;continue};$hc=$http.AcceptTcpClient();$s=$hc.GetStream();$s.ReadTimeout=4000;try{$req=Read-HttpLine $s;$h=@{};while(($l=Read-HttpLine $s) -ne ''){if($null -eq $l){break};$i=$l.IndexOf(':');if($i -gt 0){$h[$l.Substring(0,$i).ToLower()]=$l.Substring($i+1).Trim()}};$len=0;if($h.ContainsKey('content-length')){$len=[int]$h['content-length']};$body='';if($len -gt 0){$bodyBytes=New-Object byte[] $len;$offset=0;while($offset -lt $len){$n=$s.Read($bodyBytes,$offset,$len-$offset);if($n -le 0){throw 'HTTP-Anfrage unvollständig'};$offset+=$n};$body=[Text.Encoding]::UTF8.GetString($bodyBytes)};$a=$req.Split(' ');$method=$a[0];$path=$a[1].Split('?')[0];$data=$null
 if($method -eq 'GET' -and $path -eq '/') {Reply $s '200 OK' ([IO.File]::ReadAllText((Join-Path $PSScriptRoot 'index.html'))) 'text/html; charset=utf-8'}elseif($method -eq 'GET' -and $path -eq '/icon.svg'){Reply $s '200 OK' ([IO.File]::ReadAllText((Join-Path $PSScriptRoot 'icon.svg'))) 'image/svg+xml'}elseif($method -eq 'GET' -and $path -eq '/icon.ico'){Reply-Binary $s '200 OK' ([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'icon.ico'))) 'image/x-icon'}elseif($method -eq 'GET' -and $path -eq '/api/state'){$pollingError=$false;if($script:st.status -eq 'verbunden' -and $script:st.last_poll_at){$pollingError=([DateTime]::UtcNow-$script:st.last_poll_at).TotalSeconds -gt 20};$snapshot=[ordered]@{status=$script:st.status;polling_error=$pollingError;error=$script:st.error;config=$script:st.config;queue=$script:st.queue.Count;phase=$script:st.phase;events=@($script:st.events.ToArray());last_id=$script:st.next_id;traffic=$script:st.traffic};Reply $s '200 OK' (ConvertTo-Json $snapshot -Depth 12 -Compress)}elseif($method -eq 'GET' -and $path -eq '/api/ports'){$ports=@([IO.Ports.SerialPort]::GetPortNames()|ForEach-Object{@{path=$_;label=$_}});Reply $s '200 OK' (ConvertTo-Json -InputObject $ports -Compress)}elseif($method -eq 'GET' -and $path -eq '/api/export'){$snap=[ordered]@{exported_at=(Get-Date).ToString('o');events=@($script:st.events.ToArray());traffic=$script:st.traffic;config=$script:st.config};Reply $s '200 OK' (ConvertTo-Json $snap -Depth 12) 'application/json; charset=utf-8'}elseif($method -eq 'POST'){$data=ConvertFrom-Json $body;switch($path){'/api/start'{Start-Link $data;$out=@{ok=$true}}'/api/stop'{Stop-Link;$out=@{ok=$true}}'/api/reset'{$script:st.events.Clear();foreach($k in $script:st.traffic.Keys){$script:st.traffic[$k].rx=0;$script:st.traffic[$k].tx=0};$out=@{ok=$true}}'/api/send'{if($script:st.config.mode -ne 'emulator'){throw 'Zum Senden Emulatorbetrieb aktivieren'};if($script:st.queue.Count -ge 50){throw 'Warteschlange voll'};$m=Make-Block $data;$script:st.queue.Enqueue($m);Add-Event system queued $m @{info='Meldung vorgemerkt';block=(Decode-Block $m)};$out=@{ok=$true;hex=(($m|%{$_.ToString('X2')}) -join ' ')}}'/api/raw'{$hex=$data.hex -replace '[^0-9A-Fa-f]','';if(-not $hex -or $hex.Length%2){throw 'Hexdaten ungültig'};$raw=New-Object byte[] ($hex.Length/2);for($j=0;$j -lt $raw.Length;$j++){$raw[$j]=[Convert]::ToByte($hex.Substring($j*2,2),16)};if($script:st.config.mode -ne 'emulator' -or $script:st.status -ne 'verbunden'){throw 'Zum Rohversand Emulator verbinden'};Write-Link $raw 'manual';$out=@{ok=$true;hex=(($raw|%{$_.ToString('X2')}) -join ' ')}}default{throw 'Unbekannter API-Pfad'}};Reply $s '200 OK' (ConvertTo-Json $out -Compress)}else{Reply $s '404 Not Found' 'Nicht gefunden' 'text/plain; charset=utf-8'}
 }catch{try{Reply $s '400 Bad Request' (ConvertTo-Json @{ok=$false;error=$_.Exception.Message} -Compress)}catch{}}finally{$s.Dispose();$hc.Close()}}}finally{Stop-Link;$http.Stop()}
